**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("macierz.txt");
    int m[4][6], t[6][4];
    for (int i = 0; i < 4; i++)
        for (int j = 0; j < 6; j++)
            plik >> m[i][j];

    // Transpozycja
    for (int i = 0; i < 4; i++)
        for (int j = 0; j < 6; j++)
            t[j][i] = m[i][j];

    cout << "Transpozycja:" << endl;
    for (int i = 0; i < 6; i++) {
        for (int j = 0; j < 4; j++) {
            if (j > 0) cout << " ";
            cout << t[i][j];
        }
        cout << endl;
    }

    int sumW = 0, sumK = 0;
    for (int j = 0; j < 6; j++) sumW += m[0][j];
    for (int i = 0; i < 4; i++) sumK += m[i][0];

    cout << "Suma wiersza 1: " << sumW << endl;
    cout << "Suma kolumny 1: " << sumK << endl;
    cout << "Rowne: " << (sumW == sumK ? "TAK" : "NIE") << endl;
    return 0;
}
```

**Wyjasnienie**: Transpozycja zamienia wiersze na kolumny: t[j][i]=m[i][j]. Macierz 4x6 staje sie 6x4.

Weryfikacja:
- Wiersz 1 oryginalu: 1+2+3+4+5+6 = 21
- Kolumna 1 oryginalu: 1+7+6+12 = 26
- 21 != 26 -> NIE
- Transpozycja: kolumna 0 oryginalu (1,7,6,12) staje sie wierszem 0 transpozycji itd.
